const items = $input.all();

if (!items || items.length === 0) {
  return {
    json: {
      messages: [],
      total: 0
    }
  };
}

const messages = items.map(item => {
  let parsedMetadata = item.json.metadata;
  let parsedData = item.json.data;

  if (parsedMetadata && typeof parsedMetadata === 'string') {
    try { parsedMetadata = JSON.parse(parsedMetadata); } catch (e) { console.log('Meta parse err'); }
  }

  if (parsedData && typeof parsedData === 'string') {
    try { parsedData = JSON.parse(parsedData); } catch (e) { parsedData = []; }
  }

  let createdAtStr = item.json.created_at;
  if (createdAtStr) {
    const d = new Date(createdAtStr);
    const pad = (n) => String(n).padStart(2, '0');
    createdAtStr = `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`;
  }

  return {
    message_id: item.json.message_id,
    session_id: item.json.session_id,
    message_type: item.json.message_type,
    content: item.json.content,
    status_type: item.json.status_type,
    sql_query: item.json.sql_query,
    metadata: parsedMetadata,
    data: parsedData,
    user_id: item.json.user_id,
    created_at: createdAtStr
  };
});

return {
  json: {
    messages: messages,
    total: messages.length
  }
};
